#include <iostream>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;

    int n = s.length();
    int digits = 0;
    int upper = 0;
    int lower = 0;

    for (int i = 0; i < n; i++) {
        if (s[i] >= '0' && s[i] <= '9') {
            digits++;
        } else if (s[i] >= 'A' && s[i] <= 'Z') {
            upper++;
        } else if (s[i] >= 'a' && s[i] <= 'z') {
            lower++;
        }
    }

    cout << "数字：" << digits << endl;
    cout << "大写字母：" << upper << endl;
    cout << "小写字母：" << lower << endl;
    return 0;
}

